-- ============================================================================
-- Sohba (صُحبة Games Mix) — Egyptian Gaming Community Posts & 1-Minute Interval
-- 1. Full Pool of EXACTLY 200 Distinct Egyptian Gaming Community Posts:
--    - PlayStation 4 & 5, DualSense drift, PS Plus, Console deals & exclusives
--    - PC Master Race, GPUs (RTX), El-Bustan / Souq El-Asr builds, Steam sales
--    - Competitive online struggles: Egyptian ping, WE / TE Data, FC/FIFA script, Valorant, CS2, LoL
--    - Masterpiece story games: Red Dead 2, Elden Ring, The Witcher 3, GTA 6 hype
--    - Cyber cafe nostalgia: PES 6, Red Alert 2, GTA Vice City chopper, IGI
-- 2. Update schedule interval to 1 minute (v_gap := interval '1 minute')
-- 3. Reschedule active queue immediately so it takes effect right away!
-- ============================================================================

create or replace function public.demo_post_text(p_index integer, p_gender text default 'male')
returns text
language plpgsql
immutable
set search_path = public
as $$
declare
  v_idx integer;
  v_posts text[] := array[
    -- ========================================================================
    -- [1 - 20]: PlayStation, DualSense, Consoles & Store Deals
